input.command:
cd /tmp && ls -d /tmp/_MEI* 2>/dev/null | head; echo "--- run and watch /tmp"; before=$(ls /tmp | wc -l); /workspace/dataset/test6_executable --key a --val 1 >/dev/null 2>&1; after=$(ls /tmp | wc -l); echo "before=$before after=$after"; ls -d /tmp/_MEI* 2>/dev/null | head
echo "--- timing (10 runs)"; time (for i in $(seq 1 10); do /workspace/dataset/test6_executable --key a --val 1 >/dev/null 2>&1; done)
echo "--- child pid / does it fork?"; strings -a /workspace/dataset/test6_executable 2>/dev/null | grep -cE '_MEIPASS|pyi-' ; strings -a /workspace/dataset/test6_executable 2>/dev/null | grep -oE 'pyi-[a-z-]+' | sort -u | head -20

cat > /tmp/chunks.mjs <<'EOF'
import { spawn } from 'node:child_process';
function run(args, label){ return new Promise(res=>{
  const p = spawn('/workspace/dataset/test6_executable', args, {stdio:['ignore','pipe','pipe']});
  const chunks=[]; const echunks=[];
  p.stdout.on('data',d=>chunks.push([Date.now(),d]));
  p.stderr.on('data',d=>echunks.push([Date.now(),d]));
  p.on('close',(code,sig)=>{ console.log(label,'code=',code,'sig=',sig,'stdoutChunks=',chunks.map(c=>JSON.stringify(c[1].toString('latin1'))),'stderrChunks=',echunks.length); res(); });
});}
await run(['--key','a','--val','1'],'ok:');
await run(['--key','a'],'err:');
// invalid utf8 via Buffer arg is not allowed in Node; show that:
try { spawn('/workspace/dataset/test6_executable',['--val', Buffer.from([0xff]).toString('binary')]); } catch(e){ console.log('spawn latin1 ok'); }
EOF
node /tmp/chunks.mjs

cat > /tmp/argvtest.mjs <<'EOF'
import fs from 'node:fs';
const a = process.argv.slice(2);
console.log('process.argv:', a.map(s=>[...s].map(c=>c.codePointAt(0).toString(16)).join(' ')));
const raw = fs.readFileSync('/proc/self/cmdline');
const parts = raw.toString('latin1').split('\0').filter((_,i,arr)=>i<arr.length-1);
console.log('cmdline parts:', parts.length, parts.map(p=>Buffer.from(p,'latin1').toString('hex')));
EOF
node /tmp/argvtest.mjs --val $'\xff' --key $'A\xc3\xa9\xff'
